const delay = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

export default async function SpecialtiesPage() {
  await delay(2000); // Чекаємо 2 секунди

  return (
    <div>
      <h2>Список спеціальностей коледжу</h2>
      <p>Наш навчальний заклад пропонує сучасні та затребувані напрямки підготовки:</p>
      <ul>
        <li>
          <strong><a href="/specialties/programming">Програмування</a></strong> — розробка програмного забезпечення, веб та мобільних додатків.
        </li>
        <li>
          <strong><a href="/specialties/design">Дизайн</a></strong> — UI/UX дизайн, комп'ютерна графіка та візуальні комунікації.
        </li>
      </ul>
    </div>
  );
}